"use client";

import type { ImageLoaderProps } from "next/image";

/**
 * next/image loader for a static export.
 * - Unsplash / Pexels: ask the CDN for the exact width; `auto=format` serves AVIF/WebP.
 * - Self-hosted photos (/img/<name>.webp, generated by `npm run images`): picks the
 *   smallest pre-built width that covers the request.
 * - Any other local file in /public: served as-is.
 */

// Keep in sync with WIDTHS in scripts/optimize-images.mjs
const LOCAL_WIDTHS = [384, 640, 828, 1080, 1440, 1920];
export default function imageLoader({ src, width, quality }: ImageLoaderProps): string {
  const q = quality ?? 65;
  if (src.startsWith("https://images.unsplash.com")) {
    const url = new URL(src);
    url.searchParams.set("w", String(width));
    url.searchParams.set("q", String(q));
    url.searchParams.set("auto", "format");
    url.searchParams.set("fit", "crop");
    return url.toString();
  }
  if (src.startsWith("https://images.pexels.com")) {
    const url = new URL(src);
    url.searchParams.set("auto", "compress");
    url.searchParams.set("cs", "tinysrgb");
    url.searchParams.set("w", String(width));
    return url.toString();
  }
  if (src.startsWith("/img/") && src.endsWith(".webp")) {
    const w = LOCAL_WIDTHS.find((lw) => lw >= width) ?? LOCAL_WIDTHS[LOCAL_WIDTHS.length - 1];
    return src.replace(/\.webp$/, `-${w}.webp`);
  }
  return src;
}
